/* Source geometry stays separate from color recipes and is restored by the timeline. */
(() => {
 'use strict';
 const core=RayPhotoCore,make=()=>document.createElement('canvas'),workspace=document.querySelector('.film-workspace'),stage=document.getElementById('stage'),wrap=document.getElementById('canvasWrap'),basic=document.getElementById('grpBasicTone');
 let master=null,state=null,owned=null,crop=null,ratio=null;
 const panel=document.createElement('section');panel.className='photo-basic-tools';panel.innerHTML='<p class="compose-title">Xoay, cắt & lật</p><div class="seg photo-orientation"><button type="button" data-photo="left">↶ Xoay trái 90°</button><button type="button" data-photo="right">↷ Xoay phải 90°</button><button type="button" data-photo="flipX">↔ Lật ngang</button><button type="button" data-photo="flipY">↕ Lật dọc</button></div><div class="compose-actions"><button type="button" class="bbtn" id="showPhotoCrop">Cắt ảnh</button><button type="button" class="bbtn" id="resetPhotoGeometry">Về khung ảnh gốc</button></div><div id="photoCropControls" hidden><p class="hint">Kéo giữa khung để căn ảnh; kéo góc để đổi cỡ. Chọn tỉ lệ rồi bấm Cắt theo khung.</p><div class="photo-crop-ratios" role="group" aria-label="Tỉ lệ cắt ảnh"></div><div class="compose-actions"><button type="button" class="bbtn" id="applyPhotoCrop">Cắt theo khung ✓</button><button type="button" class="bbtn" id="cancelPhotoCrop">Hủy cắt</button></div></div><p class="hint" id="photoGeometryStatus">Ảnh gốc vẫn được giữ trong bản nháp. Quay lại để hoàn tác.</p>';
 basic.querySelector('.lbl').after(panel);
 const cropControls=panel.querySelector('#photoCropControls'),status=panel.querySelector('#photoGeometryStatus'),frame=document.createElement('div');frame.id='photoCropFrame';frame.className='photo-crop-frame';frame.hidden=true;frame.setAttribute('aria-label','Khung cắt ảnh');const size=document.createElement('button');size.type='button';size.className='photo-crop-size';size.textContent='↔';size.setAttribute('aria-label','Kéo để đổi cỡ khung cắt');frame.append(size);wrap.append(frame);
 function reset(){if(owned){owned.width=owned.height=0;owned=null;}if(master&&master!==source)master.close?.();master=source;state=master?core.initial(master.width,master.height):null;crop=null;sync();}
 function restore(value){if(!master)return;const next=value?.matrix?.length===6?value:core.initial(master.width,master.height);if(state&&JSON.stringify(state)===JSON.stringify(next))return;state={width:next.width,height:next.height,matrix:next.matrix.slice()};const old=owned,isOriginal=state.width===master.width&&state.height===master.height&&state.matrix.every((v,i)=>v===[1,0,0,1,0,0][i]);owned=isOriginal?null:core.render(master,state,make);source=owned||master;preview=makePreview(source);if(old&&old!==source)old.width=old.height=0;window.RayBodyPeople?.sourceChanged();window.RayCompose?.sourceChanged();window.RayRemove?.sourceChanged();window.BuongToiApp?.refreshThumbnails();crop=null;sync();}
 function perform(op,label){if(!source||BEAUTY.busy||BODY_AI.busy||(window.RayCompose?.busy||window.RayRemove?.busy))return;window.RaySession.record();const snap=window.RaySession.snapshot(),mapped=core.remap(snap,source.width,source.height,op);mapped.photo=core.next(state,op);window.RaySession.restoreSnapshot(mapped);crop=null;sync();queue();window.RaySession.record(label);}
 panel.querySelector('.photo-orientation').onclick=e=>{const kind=e.target.closest('button')?.dataset.photo;if(kind&&source)perform(core.operation(source.width,source.height,kind),'Xoay / lật ảnh');};
 panel.querySelector('#showPhotoCrop').onclick=()=>{crop=crop?null:core.fitCrop(source.width,source.height,ratio);sync();};panel.querySelector('#cancelPhotoCrop').onclick=()=>{crop=null;sync();};
 panel.querySelector('#applyPhotoCrop').onclick=()=>{if(crop)perform(core.operation(source.width,source.height,'crop',crop),'Cắt ảnh');};
 panel.querySelector('#resetPhotoGeometry').onclick=()=>{if(!master||!state)return;perform({width:master.width,height:master.height,matrix:core.inverse(state.matrix)},'Về khung ảnh gốc');};
 for(const [label,value]of [['Tự do',null],['Gốc','original'],['1:1',1],['4:5',.8],['3:4',.75],['9:16',9/16],['16:9',16/9]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.dataset.ratio=String(value);b.onclick=()=>{ratio=value==='original'?master.width/master.height:value;crop=core.fitCrop(source.width,source.height,ratio);sync();};panel.querySelector('.photo-crop-ratios').append(b);}
 function geometry(){return bodyGeo();}
 RayControls.bindDrag(frame,{start(e){if(e.target===size||!crop)return;const g=geometry();if(!g)return;return{...crop,g};},move(s,p){crop={...crop,x:clamp(s.x+p.dx/(s.g.W*s.g.k),0,1-crop.width),y:clamp(s.y+p.dy/(s.g.H*s.g.k),0,1-crop.height)};syncFrame();}});
 RayControls.bindDrag(size,{start(){const g=geometry();if(!crop||!g)return;return{...crop,g};},move(s,p){let width=clamp(s.width+p.dx/(s.g.W*s.g.k),.05,1-s.x),height=clamp(s.height+p.dy/(s.g.H*s.g.k),.05,1-s.y);if(ratio){height=width*s.g.W/ratio/s.g.H;if(height>1-s.y){height=1-s.y;width=height*ratio*s.g.H/s.g.W;}}crop={x:s.x,y:s.y,width,height};syncFrame();}});
 function syncFrame(){const editing=!!source&&!!crop&&document.body.dataset.editorTool==='adjust'&&['Cơ bản','Tất cả'].includes(window.RayControls.captureSelection()?.adjustName)&&!workspace.classList.contains('is-result-preview');frame.hidden=!editing;stage.classList.toggle('photo-cropping',editing);if(!editing)return;const g=geometry(),wr=wrap.getBoundingClientRect();if(g)Object.assign(frame.style,{left:g.ox-wr.left+crop.x*g.W*g.k+'px',top:g.oy-wr.top+crop.y*g.H*g.k+'px',width:crop.width*g.W*g.k+'px',height:crop.height*g.H*g.k+'px'});}
 function sync(){const disabled=!source||BEAUTY.busy||BODY_AI.busy||(window.RayCompose?.busy||window.RayRemove?.busy);panel.querySelectorAll('button').forEach(b=>b.disabled=disabled);cropControls.hidden=!crop;panel.querySelector('#showPhotoCrop').textContent=crop?'Ẩn khung cắt':'Cắt ảnh';status.textContent=source?source.width+' × '+source.height+' px · Ảnh gốc vẫn được giữ trong bản nháp.':'Mở ảnh để xoay, cắt hoặc lật.';syncFrame();}
 const oldDraw=draw;draw=function(){oldDraw();sync();};const oldSync=syncControls;syncControls=function(){oldSync();sync();};const toolChange=RayControls.onToolChange;RayControls.onToolChange=function(tool){toolChange(tool);sync();};new ResizeObserver(syncFrame).observe(wrap);
 window.RayPhotoEdit={capture:()=>state,restore,reset,cancelCrop(){crop=null;sync();},original:()=>master};sync();
})();
